parts.text:
{
  "story_seeds": [
    {
      "seed": "El último aliento de un hechicero caído, buscando reescribir un destino que se le escapa entre los dedos como arena.",
      "suggested_genre": "Tragedia"
    },
    {
      "seed": "La melancolía de un coleccionista de reliquias, cuyo tesoro más preciado es un recuerdo intangible de un amor perdido.",
      "suggested_genre": "Romance Melancólico"
    },
    {
      "seed": "Los susurros de una armadura olvidada, que atestiguan las batallas y los miedos de los guerreros que la vistieron.",
      "suggested_genre": "Terror Psicológico"
    },
    {
      "seed": "La devoción inquebrantable de un sirviente leal, que sigue esperando el regreso de un señor que ya no existe.",
      "suggested_genre": "Devoción y Soledad"
    },
    {
      "seed": "El eco de una risa infantil en las ruinas de un castillo, una presencia fantasma que recuerda tiempos más luminosos.",
      "suggested_genre": "Misterio Fantasmal"
    },
    {
      "seed": "La amargura de un rey despojado, cuyo orgullo se aferra a los fantasmas de su antigua gloria.",
      "suggested_genre": "Drama Histórico"
    },
    {
      "seed": "El viaje de un peregrino sin nombre, impulsado por un juramento olvidado y la promesa de una curación esquiva.",
      "suggested_genre": "Aventura y Fe"
    },
    {
      "seed": "La desesperación de un artesano, forzando su vida en la creación de un objeto que pueda desafiar la corrupción.",
      "suggested_genre": "Creación y Sacrificio"
    },
    {
      "seed": "Los secretos guardados en el corazón de un bosque ancestral, donde los árboles mismos recuerdan la venida de los dioses.",
      "suggested_genre": "Fantasía Épica"
    },
    {
      "seed": "La contemplación de un alma errante sobre la naturaleza cíclica del poder y la decadencia.",
      "suggested_genre": "Reflexión Filosófica"
    },
    {
      "seed": "El lamento de un cazador de monstruos, atormentado por los rostros de las criaturas que ha matado, incapaz de distinguir el bien del mal.",
      "suggested_genre": "Existencial"
    },
    {
      "seed": "La historia no contada de un grito ahogado durante un ritual oscuro, un fragmento de voluntad que se niega a desaparecer.",
      "suggested_genre": "Horror Oculto"
    },
    {
      "seed": "La soledad de una guardiana en una torre olvidada, cuya vigilia se ha prolongado por siglos, esperando un peligro que quizás nunca llegue.",
      "suggested_genre": "Soledad y Deber"
    },
    {
      "seed": "La perspectiva de un antiguo espejo, que ha reflejado el ascenso y la caída de innumerables civilizaciones, observando la fragilidad de la existencia.",
      "suggested_genre": "Observación Cósmica"
    }
  ]
}

{
  "story_seeds": [
    {
      "seed": "El último susurro de un alma perdida en el Bosque de la Desesperación: un eco fantasmal que revela un pacto olvidado con una entidad oscura y los terribles sacrificios que lo precedieron.",
      "suggested_genre": "Misterio"
    },
    {
      "seed": "La espada olvidada por un caballero caído en la batalla del Santuario de los Huesos: el misterio de su origen y la verdad sobre la promesa que hizo antes de sucumbir.",
      "suggested_genre": "Tragedia"
    },
    {
      "seed": "El susurro de las ruinas del Asentamiento: la historia de una joven aprendiz de hechicera que se vio obligada a ocultar una verdad impactante para proteger a sus seres queridos.",
      "suggested_genre": "Drama"
    },
    {
      "seed": "La profecía de los cráneos de cristal en la Torre de la Oscuridad: una profecía que se materializa en el presente, un enigma que requiere la ayuda de un alquimista para interpretar el futuro",
      "suggested_genre": "Aventura"
    },
    {
      "seed": "La maldición de un tesoro prohibido, guardado en la Cueva de la Sombra: la historia de un mercenario que deberá enfrentarse a sus propias sombras para proteger el equilibrio.",
      "suggested_genre": "Terror Psicológico"
    },
    {
      "seed": "El dilema de un caballero que fue testigo de la destrucción de la ciudad sagrada: ¿Honrar su juramento a un dios caído o buscar su propia redención? ¿Cuál es el costo de la neutralidad?",
      "suggested_genre": "Dilema moral"
    },
    {
      "seed": "La leyenda de una reliquia ancestral, escondida en los restos de un templo abandonado: una búsqueda por un artefacto antiguo que podría cambiar el destino del mundo.",
      "suggested_genre": "Aventura"
    },
    {
      "seed": "La soledad de una bestia sagrada, encarcelada en los calabozos del rey: un misterio que desvela la naturaleza del poder y el sacrificio de los dioses antiguos",
      "suggested_genre": "Misterio"
    },
    {
      "seed": "Un antiguo pacto entre elfos y humanos que se rompió siglos atrás: un evento que causó el descenso a la oscuridad y la destrucción de sus reinos, contado por la última guardiana del Santuario.",
      "suggested_genre": "Tragedia"
    },
     {
      "seed": "Las consecuencias de una promesa rota a un dios olvidado: ¿Se puede reparar la ruina creada por las acciones pasadas?",
      "suggested_genre": "Reflexión filosófica"
    },
    {
      "seed": "El origen del mal que corrompe el Bosque de Cenizas, y el testimonio de un explorador que lo vio crecer.",
      "suggested_genre": "Terror psicológico"
    }
  ]
}
